{
  "type": "Educational Physics Infographic Poster",
  "topic": "Magnus effect",
  "style": "This minimalist academic poster combines high-end textbook design with modern aesthetics. It features symmetrical simplicity, balanced spacing, a soft, neutral cream background, and a thin cyan border. The title uses an elegant serif font, while the explanatory text employs a minimalist sans-serif font. The color scheme is limited to cyan, soft gold, dark gray, and light beige.",
  "layout": {
    "orientation": "Square poster",
    "sections": [
      {
        "title": "Magnus effect",
        "position": "Centered at the top",
        "count": 1,
        "labels": [
          "Main title"
        ]
      },
      {
        "title": "1. Definition of the phenomenon",
        "position": "Upper area",
        "count": 2,
        "labels": [
          "Define text box",
          "The small icon in the upper right corner shows a rotating sphere with a curved arrow and a gold force label F_M."
        ]
      },
      {
        "title": "2. Interaction between fluid flow and rotation",
        "position": "Central region",
        "count": 2,
        "labels": [
          "Non-rotational (symmetric flow)",
          "There is rotation (asymmetric flow)"
        ]
      },
      {
        "title": "3. Pressure difference (Bernoulli's principle)",
        "position": "bottom left corner",
        "count": 4,
        "labels": [
          "Low pressure (P1) / P1 &lt; P2",
          "Rotating sphere with a golden rotating arrow",
          "High voltage (P2) / P2 &gt; P1",
          "Bernoulli's Principle Formula Box"
        ]
      },
      {
        "title": "4. Resultant force and bending path",
        "position": "bottom right corner",
        "count": 4,
        "labels": [
          "The sphere is marked with pressure labels P1 &lt; P2 on the top and bottom.",
          "An upward-pointing gold arrow marked F_M (Magnus force)",
          "The gray dashed line represents the original path.",
          "The cyan dashed line represents the curved trajectory."
        ]
      }
    ],
    "dividers": "Four thin cyan horizontal and vertical dividing lines divide the poster into different areas and a two-column panel at the bottom."
  },
  "content_details": {
    "section_1": {
      "heading": "1. Definition of the phenomenon",
      "body": "When a rotating object moves in a fluid (gas or liquid), a lateral force is generated, causing it to deviate from its original flight path.",
      "diagram": "A simple gray sphere icon with a curved rotating arrow at the top, an outward-curving motion arrow, and a small rounded gold square containing F_M."
    },
    "section_2": {
      "heading": "2. Interaction between fluid flow and rotation",
      "panels": [
        {
          "title": "Non-rotational (symmetric flow)",
          "diagram": "A gray sphere is located at the center of a light-colored grid. Six cyan horizontal streamlines flow from left to right and curve symmetrically around the sphere. Small cyan arrows indicate that the flow velocity is equal above and below the sphere."
        },
        {
          "title": "There is rotation (asymmetric flow)",
          "diagram": "The gray sphere is surrounded by two rotating gold arrows at the center of a light-colored grid. Six cyan streamlines are compressed and flow faster above the sphere, while they are sparser below. The label on the right indicates that the area near the upper streamlines is 'fast flow, v↑', and the area near the lower streamlines is 'slow flow, v↓'. There is a subtle gold highlight wedge behind the fluid area in the upper right corner."
        }
      ]
    },
    "section_3": {
      "heading": "3. Pressure difference (Bernoulli's principle)",
      "elements": [
        "Rounded rectangle at the top with a low-pressure label",
        "A central rotating sphere with a golden curved arrow.",
        "A large, vertically downward gold arrow indicates the pressure gradient (ΔP).",
        "Rounded rectangle at the bottom, with high voltage label",
        "A large formula box containing Bernoulli's equation"
      ],
      "text_boxes": {
        "top": "Low pressure (P1) P1 &lt; P2",
        "bottom": "High voltage (P2) P2 &gt; P1",
        "formula": "Bernoulli's Principle: P + 1/2 ρv^2 = constant ⇒ ΔP ∝ (v1^2 − v2^2)",
        "caption": "The faster the flow rate (v↑), the lower the pressure (P↓)."
      }
    },
    "section_4": {
      "heading": "4. Resultant force and bending path",
      "diagram": "A large central sphere, filled with a gradient from cyan to gold, has a gold, curved, rotating arrow encircling its left side. A thick, upward-pointing gold arrow extends from the top, labeled F_M (Magnus Force). A thin, gray, dashed horizontal arrow marks the original path and extends to the right. A cyan, dashed, curved trajectory extends upwards and to the right in an arc, also bearing an arrow.",
      "caption_box": "The net Magnus force (F_M) acts at a position perpendicular to the axis of rotation and the direction of motion, thereby generating lift or a bending trajectory."
    }
  },
  "rendering": "Clear vector-style infographics, subtle paper texture, high readability, slight shading only within rounded label boxes, precise alignment, and understated scientific aesthetics."
}

